#!/usr/bin/env node
// Builds the control plane's web page into packages/control-plane/src/ui-assets.ts from packages/control-plane/ui.
// TypeScript is transpiled in-process (typescript.transpileModule), so this runs inside sandboxes that cannot spawn
// processes. The output is deterministic: files sorted by path, LF line endings, no timestamps.
// usage: node packages/control-plane/scripts/build-ui.mjs [--check]   (--check exits 1 when the file is out of date)
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import ts from 'typescript';

const PACKAGE = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const UI_DIR = join(PACKAGE, 'ui');
export const UI_OUT = join(PACKAGE, 'src', 'ui-assets.ts');

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
};

/** Returns the generated module text for the ui directory (flat: index.html, app.ts, app.css, icon.svg). */
export async function buildControlPlaneUi(dir = UI_DIR) {
  const assets = [];
  for (const file of (await readdir(dir)).sort()) {
    let name = file;
    let body;
    if (file.endsWith('.d.ts')) continue;
    if (file.endsWith('.ts')) {
      name = file.replace(/\.ts$/, '.js');
      body = ts.transpileModule((await readFile(join(dir, file), 'utf8')).replace(/\r\n/g, '\n'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022, removeComments: false },
        fileName: file,
      }).outputText.replace(/\r\n/g, '\n').replace(/\n\/\/# sourceMappingURL=.*$/m, '');
    } else if (/\.(html|css|svg)$/.test(file)) {
      body = (await readFile(join(dir, file), 'utf8')).replace(/\r\n/g, '\n');
    } else {
      continue;
    }
    const type = TYPES[name.slice(name.lastIndexOf('.'))];
    assets.push([name === 'index.html' ? '/' : `/app/${name}`, { type, body }]);
  }
  return [
    '// Generated by packages/control-plane/scripts/build-ui.mjs from packages/control-plane/ui. Do not edit; run',
    '// `node packages/control-plane/scripts/build-ui.mjs`.',
    'export interface UiAsset { type: string; body: string }',
    'export const UI_ASSETS: Readonly<Record<string, UiAsset>> = {',
    ...assets.map(([path, asset]) => `  ${JSON.stringify(path)}: ${JSON.stringify(asset)},`),
    '};',
    '',
  ].join('\n');
}

async function main() {
  const text = await buildControlPlaneUi();
  if (process.argv.includes('--check')) {
    const current = await readFile(UI_OUT, 'utf8').catch(() => '');
    if (current.replace(/\r\n/g, '\n') !== text) {
      console.error('packages/control-plane/src/ui-assets.ts is out of date. Run: node packages/control-plane/scripts/build-ui.mjs');
      process.exitCode = 1;
    }
    return;
  }
  await writeFile(UI_OUT, text);
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) await main();
